const { useState, useEffect, useMemo, useCallback, useRef } = React;

/* ---------- dil (TR / EN) ----------
   Cihaz dili Türkçe ise Türkçe, değilse İngilizce. Veri/haber kaynakları Türkçe kalır.
   t("türkçe", "english") — yazım yerinde iki dilli metin. */
const LANG_EN = (() => {
  try {
    if (typeof window !== "undefined" && window.__YN_LANG__) return window.__YN_LANG__ !== "tr";
    const l = (typeof navigator !== "undefined" && ((navigator.languages && navigator.languages[0]) || navigator.language)) || "tr";
    return !/^tr\b/i.test(l);
  } catch (e) { return false; }
})();
const LOC = LANG_EN ? "en-US" : "tr-TR";
const t = (tr, en) => (LANG_EN ? en : tr);
// Arama: Türkçe modda eskisi gibi; İngilizce modda ı/ç/ğ/ö/ş/ü harfleri ASCII karşılığıyla eşleşir
const aramaNorm = (s) => {
  const x = String(s).toLocaleLowerCase("tr-TR");
  return LANG_EN ? x.replace(/[ıçğöşü]/g, (c) => ({ "ı": "i", "ç": "c", "ğ": "g", "ö": "o", "ş": "s", "ü": "u" })[c]) : x;
};

/* =========================================================================
   YAKIT NABZI — Türkiye geneli akaryakıt fiyat değişim takipçisi
   3 sekme: Şehirler (il/ilçe seçimi) · Değişim (günlük takip)
   · Hakkında (indir, puan ver, gizlilik, paylaş)
   ========================================================================= */

/* ---------- kalıcı depolama katmanı ----------
   window.storage sadece Claude.ai'nin artifact önizleyicisinde bulunur.
   Bağımsız/yayınlanmış uygulamada aynı arayüzü (get/set/delete/list) veren,
   localStorage tabanlı bir karşılık koyuyoruz — böylece geri kalan kod
   (persistFavorites, persistPrefs, vb.) değişmeden çalışır.
   Not: React Native / Capacitor'a taşırken bu bloğu AsyncStorage veya
   Capacitor Preferences ile değiştirmek yeterli, çağrı yapan kodun
   hiçbirine dokunmanıza gerek yok. */
if (typeof window !== "undefined" && !window.storage) {
  const NS = "yakitNabzi:"; // localStorage anahtar çakışmalarını önlemek için
  window.storage = {
    async get(key, shared = false) {
      try {
        const raw = window.localStorage.getItem(NS + (shared ? "shared:" : "") + key);
        if (raw === null) return null;
        return { key, value: raw, shared: !!shared };
      } catch (e) {
        throw new Error("storage.get başarısız: " + e.message);
      }
    },
    async set(key, value, shared = false) {
      try {
        window.localStorage.setItem(NS + (shared ? "shared:" : "") + key, value);
        return { key, value, shared: !!shared };
      } catch (e) {
        // Örn. localStorage kotası dolduğunda (QuotaExceededError) buraya düşer
        throw new Error("storage.set başarısız: " + e.message);
      }
    },
    async delete(key, shared = false) {
      try {
        window.localStorage.removeItem(NS + (shared ? "shared:" : "") + key);
        return { key, deleted: true, shared: !!shared };
      } catch (e) {
        throw new Error("storage.delete başarısız: " + e.message);
      }
    },
    async list(prefix = "", shared = false) {
      try {
        const base = NS + (shared ? "shared:" : "");
        const keys = [];
        for (let i = 0; i < window.localStorage.length; i++) {
          const k = window.localStorage.key(i);
          if (k && k.startsWith(base + prefix)) keys.push(k.slice(base.length));
        }
        return { keys, prefix, shared: !!shared };
      } catch (e) {
        throw new Error("storage.list başarısız: " + e.message);
      }
    },
  };
}

function round2(n) {
  return Math.round(n * 100) / 100;
}
function fmtTL(n) {
  if (n === null || n === undefined || Number.isNaN(n)) return "—";
  return n.toLocaleString(LOC, { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}
function fmtDelta(n) {
  if (n === null || n === undefined || Number.isNaN(n)) return t("veri yok", "no data");
  const v = Math.abs(round2(n));
  if (v < 0.02) return t("sabit", "flat");
  return (n > 0 ? "+" : "−") + v.toLocaleString(LOC, { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

/* ---------- "Sonraki Değişim" tarih biçimlendirme ---------- */
// beklenti.tarih "YYYY-MM-DD" formatında geliyor (scripts/fetch-haberler.js).
function fmtBeklentiTarihKisa(isoTarih) {
  if (!isoTarih) return "";
  const [y, m, d] = isoTarih.split("-").map(Number);
  if (LANG_EN) return new Date(y, m - 1, d).toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" });
  return String(d).padStart(2, "0") + "." + String(m).padStart(2, "0") + "." + y;
}

