const STORE_URL_IOS = "";
const STORE_URL_ANDROID = "";
const GIZLILIK_URL = "https://www.hudhudapps.com/#gizlilik";

function normalizeFuel(f) {
  const veriVar = typeof f.today === "number" && typeof f.yesterday === "number";
  const history = f.history && f.history.length ? f.history.filter((v) => typeof v === "number") : [f.yesterday, f.today].filter((v) => typeof v === "number");
  return {
    today: f.today,
    yesterday: f.yesterday,
    delta: veriVar ? round2(f.today - f.yesterday) : null,
    history: history.length ? history : [0],
  };
}

async function fetchFiyatlar() {
  const { data, cevrimdisi } = await veriGetir(FIYAT_JSON_URL, "fiyatlar");
  return {
    cevrimdisi,
    guncelleme: data.guncelleme || null,
    // "Ulusal Nabız" artık ayrı bir üçüncü parti API'den değil, aynı statik
    // JSON'ın içindeki "ulusal" alanından geliyor (EPDK'nin resmi günlük
    // bültenine dayanıyor — bkz. scripts/fetch-epdk-fiyat.js).
    ulusal: data.ulusal
      ? { benzin: data.ulusal.benzin, motorin: data.ulusal.motorin, lpg: data.ulusal.lpg }
      : null,
    districts: (data.ilceler || []).map((d) => ({
      id: d.il + "|" + d.ilce,
      il: d.il,
      ilce: d.ilce,
      kaynak: d.kaynak || null,
      benzin: normalizeFuel(d.benzin),
      motorin: normalizeFuel(d.motorin),
      lpg: normalizeFuel(d.lpg),
    })),
  };
}

/* ---------- haberler ----------
   fiyatlar.json ile aynı desen: statik bir JSON dosyası, günde birkaç kez
   GitHub Actions tarafından BİRDEN FAZLA RSS kaynağından süzülüp
   birleştiriliyor (bkz. scripts/fetch-haberler.js). Her habere hangi
   ajanstan geldiğini belirten bir "kaynak" alanı ekleniyor, böylece
   uygulama kaynağa göre etiket/filtre gösterebiliyor.

   Beklenen JSON biçimi:
   {
     "guncelleme": "2026-09-01T00:12:00+03:00",
     "kaynaklar": ["AA", "İHA", "DHA"],
     "haberler": [
       { "baslik": "...", "ozet": "...", "link": "https://...",
         "tarih": "2026-08-31T21:40:00+03:00", "kaynak": "AA" },
       ...
     ]
   } */
const HABER_JSON_URL = "https://cahitkucukofficial.github.io/yakit-nabzi/haberler.json";

function beklentiKaynakFiltre(b, kapali) {
  if (!b || !kapali.length) return b;
  const sonuc = { ...b };
  for (const urun of Object.keys(b)) {
    const v = b[urun];
    if (!v || !v.expected || !Array.isArray(v.kaynaklar)) continue;
    const kalan = v.kaynaklar.filter((k) => !kapali.includes(k.kaynak));
    if (kalan.length === 0) { sonuc[urun] = { expected: false }; continue; }
    const ilkKapali = kapali.includes(v.kaynak);
    sonuc[urun] = { ...v, kaynaklar: kalan, dogrulayanKaynakSayisi: kalan.length,
      kaynak: ilkKapali ? kalan[0].kaynak : v.kaynak, kaynakLink: ilkKapali ? kalan[0].kaynakLink : v.kaynakLink };
  }
  return sonuc;
}

async function fetchHaberler() {
  const { data } = await veriGetir(HABER_JSON_URL, "haberler");
  const haberler = (!HABERLER_OZELLIGI ? [] : (data.haberler || [])).filter((h) => !YASAKLI_KAYNAKLAR.includes(h.kaynak)).map((h, i) => ({
    id: h.link || String(i),
    baslik: h.baslik,
    link: h.link,
    tarih: h.tarih,
    kaynak: h.kaynak || null,
  }));
  const kaynaklar = data.kaynaklar && data.kaynaklar.length
    ? data.kaynaklar.filter((k) => !YASAKLI_KAYNAKLAR.includes(k))
    : Array.from(new Set(haberler.map((h) => h.kaynak).filter(Boolean)));
  return { guncelleme: data.guncelleme || null, haberler, kaynaklar, beklenti: data.beklenti || null };
}

